import {
  RadioGroup as RadioGroupPrimitive,
  useRadioGroup,
  useRadioGroupContext,
  useRadioGroupItemContext,
} from '@ark-ui/solid/radio-group';
import { clsx } from 'clsx';
import type { ComponentProps, JSX } from 'solid-js';
import { splitProps } from 'solid-js';
import styles from './RadioGroup.module.css';

type RadioGroupSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type RadioGroupRootProps = ComponentProps<typeof RadioGroupPrimitive.Root> & {
  size?: RadioGroupSize;
};
type RadioGroupRootProviderProps = ComponentProps<typeof RadioGroupPrimitive.RootProvider> & {
  size?: RadioGroupSize;
};
type RadioGroupOptionProps = Omit<
  ComponentProps<typeof RadioGroupPrimitive.Item>,
  'asChild' | 'children'
> & {
  children: JSX.Element;
};

function RadioGroup(props: RadioGroupRootProps) {
  const [local, others] = splitProps(props, ['class', 'size']);

  return (
    <RadioGroupPrimitive.Root
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="radio-group-root"
      class={clsx(styles.root, local.class)}
    />
  );
}

function RadioGroupRootProvider(props: RadioGroupRootProviderProps) {
  const [local, others] = splitProps(props, ['class', 'size']);

  return (
    <RadioGroupPrimitive.RootProvider
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="radio-group-root-provider"
      class={clsx(styles.root, local.class)}
    />
  );
}

function RadioGroupLabel(props: ComponentProps<typeof RadioGroupPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <RadioGroupPrimitive.Label
      {...others}
      data-slot="radio-group-label"
      class={clsx(styles.label, local.class)}
    />
  );
}

function RadioGroupItem(props: ComponentProps<typeof RadioGroupPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <RadioGroupPrimitive.Item
      {...others}
      data-slot="radio-group-item"
      class={clsx(styles.item, local.class)}
    />
  );
}

function RadioGroupOption(props: RadioGroupOptionProps) {
  const [local, others] = splitProps(props, ['children']);

  return (
    <RadioGroupItem {...others}>
      <RadioGroupPrimitive.ItemHiddenInput />
      <RadioGroupItemControl />
      <RadioGroupItemText>{local.children}</RadioGroupItemText>
    </RadioGroupItem>
  );
}

function RadioGroupItemControl(props: ComponentProps<typeof RadioGroupPrimitive.ItemControl>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <RadioGroupPrimitive.ItemControl
      {...others}
      data-slot="radio-group-item-control"
      class={clsx(styles.itemControl, local.class)}
    />
  );
}

function RadioGroupItemText(props: ComponentProps<typeof RadioGroupPrimitive.ItemText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <RadioGroupPrimitive.ItemText
      {...others}
      data-slot="radio-group-item-text"
      class={clsx(styles.itemText, local.class)}
    />
  );
}

function RadioGroupIndicator(props: ComponentProps<typeof RadioGroupPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <RadioGroupPrimitive.Indicator
      {...others}
      data-slot="radio-group-indicator"
      class={clsx(styles.indicator, local.class)}
    />
  );
}

const RadioGroupContext = RadioGroupPrimitive.Context;
const RadioGroupItemContext = RadioGroupPrimitive.ItemContext;
const RadioGroupItemHiddenInput = RadioGroupPrimitive.ItemHiddenInput;

export {
  RadioGroup,
  RadioGroupContext,
  RadioGroupIndicator,
  RadioGroupItem,
  RadioGroupItemContext,
  RadioGroupItemControl,
  RadioGroupItemHiddenInput,
  RadioGroupItemText,
  RadioGroupLabel,
  RadioGroupOption,
  RadioGroupRootProvider,
  useRadioGroup,
  useRadioGroupContext,
  useRadioGroupItemContext,
};
export type {
  RadioGroupOptionProps,
  RadioGroupRootProps,
  RadioGroupRootProviderProps,
  RadioGroupSize,
};

@layer moduix.components {
  .root {
    --_radio-size: var(--moduix-spacing-5);
    --_radio-indicator-size: var(--moduix-spacing-2);

    display: flex;
    flex-direction: column;
    gap: var(--moduix-spacing-2);
    color: var(--moduix-color-foreground);

    &[data-size='xs'] {
      --_radio-size: var(--moduix-spacing-3-5);
      --_radio-indicator-size: var(--moduix-spacing-1);
    }

    &[data-size='sm'] {
      --_radio-size: var(--moduix-spacing-4);
      --_radio-indicator-size: var(--moduix-spacing-1-5);
    }

    &[data-size='lg'] {
      --_radio-size: var(--moduix-size-xs);
      --_radio-indicator-size: var(--moduix-spacing-2-5);
    }

    &[data-size='xl'] {
      --_radio-size: var(--moduix-spacing-7);
      --_radio-indicator-size: var(--moduix-spacing-3);
    }
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-sm);
  }

  .item {
    display: inline-flex;
    align-items: center;
    width: fit-content;
    gap: var(--moduix-radio-gap, var(--moduix-spacing-2));
    vertical-align: middle;
    cursor: pointer;

    &[data-disabled],
    &[data-readonly] {
      cursor: default;
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .itemControl {
    box-sizing: border-box;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    width: var(--moduix-radio-size, var(--_radio-size));
    height: var(--moduix-radio-size, var(--_radio-size));
    border: var(--moduix-border-width-sm) solid
      var(--moduix-radio-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-radio-bg, var(--moduix-color-background));
    color: var(--moduix-radio-indicator-color, var(--moduix-color-primary-foreground));
    user-select: none;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default);

    &::before {
      width: var(--moduix-radio-indicator-size, var(--_radio-indicator-size));
      height: var(--moduix-radio-indicator-size, var(--_radio-indicator-size));
      border-radius: var(--moduix-radius-full);
      background-color: currentColor;
      content: '';
      opacity: 0;
      transform: scale(0.6);
      transition:
        opacity var(--moduix-transition-default),
        transform var(--moduix-transition-default);
    }

    &[data-state='checked'] {
      border-color: var(--moduix-radio-bg-checked, var(--moduix-color-primary));
      background-color: var(--moduix-radio-bg-checked, var(--moduix-color-primary));

      &::before {
        opacity: 1;
        transform: scale(1);
      }
    }

    &[data-focus-visible] {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);
      outline-color: var(--moduix-color-destructive);
    }

    @media (hover: hover) {
      &[data-state='unchecked'][data-hover]:not([data-readonly], [data-disabled]) {
        background-color: var(--moduix-color-accent);
      }
    }
  }

  .itemText {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .indicator {
    --transition-duration: var(--moduix-duration-normal);
    --transition-timing-function: var(--moduix-ease-in-out);

    top: var(--top);
    left: var(--left);
    width: var(--width);
    height: var(--height);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-primary);
    opacity: 0.12;
    pointer-events: none;
  }
}
